package com.example.im.auth;
import com.example.im.auth.dto.*; import com.example.im.security.JwtService; import com.example.im.user.*; import io.jsonwebtoken.Claims; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class AuthService {private final UserRepository repo;private final PasswordEncoder encoder;private final JwtService jwt; public AuthService(UserRepository repo,PasswordEncoder encoder,JwtService jwt){this.repo=repo;this.encoder=encoder;this.jwt=jwt;}
 public AuthResponse register(RegisterRequest r){if(r.username()==null||r.username().isBlank()||r.password()==null||r.password().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"用户名和密码不能为空");String n=r.username().trim();if(repo.findByUsername(n).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"用户名已经存在");User u=new User();u.setUsername(n);u.setPassword(encoder.encode(r.password()));u.setDisplayName(r.displayName()==null||r.displayName().isBlank()?n:r.displayName().trim());return response(repo.save(u));}
 public AuthResponse login(LoginRequest r){User u=repo.findByUsername(r.username()==null?"":r.username().trim()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"用户名或密码错误"));boolean ok=encoder.matches(r.password(),u.getPassword())||Objects.equals(r.password(),u.getPassword());if(!ok)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"用户名或密码错误");if(!u.getPassword().startsWith("$2")){u.setPassword(encoder.encode(r.password()));repo.save(u);}return response(u);}
 public AuthResponse refresh(RefreshRequest r){try{if(r.refreshToken()==null||!jwt.isType(r.refreshToken(),"REFRESH"))throw new Exception();Claims c=jwt.parse(r.refreshToken());User u=repo.findById(c.get("userId",Long.class)).orElseThrow();return response(u);}catch(Exception e){throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Refresh Token无效或已过期");}}
 private AuthResponse response(User u){Map<String,Object> info=new HashMap<>();info.put("id",u.getId());info.put("username",u.getUsername());info.put("displayName",u.getDisplayName()==null?u.getUsername():u.getDisplayName());return new AuthResponse(jwt.access(u.getId(),u.getUsername()),jwt.refresh(u.getId(),u.getUsername()),"Bearer",jwt.accessSeconds(),info);}}
